head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst75500";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst75500.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    $c.util.getComponent("detailContents").setStyle("display", "none");
    // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
    //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "3 ') */
    await scwin.fnSearch();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst75500.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst75500.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst75500.btn_fnSearchInit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnFileDown
 * @description fn File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnFileDown = async function () {
    const sbmOptions = {
        id: "tx_fnFileDown",
        method: "post",
        action: "/common/fileupload.do",
        ref: "dma_fnFileDownReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    try { return await $c.data.downFile("/corpgeneral/corpResearchReport.do", "", ($c.util.getComponent("dma_fnSearchAjaxsubmitReq") ? $c.util.getComponent("dma_fnSearchAjaxsubmitReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fnDetailView_ajaxsubmit
 * @description fn Detail View ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDetailView_ajaxsubmit = async function () {
    try { return await $c.data.downFile("/corpgeneral/corpResearchReport.do", "", ($c.util.getComponent("dma_fnDetailViewAjaxsubmitReq") ? $c.util.getComponent("dma_fnDetailViewAjaxsubmitReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            await scwin.fnSearchInit();
        }
    }
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    scwin.fnDetailClose();
    $c.util.getComponent("dma_fnFileDownReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_startDate').getValue())) {
        await $c.win.alert("Start Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_endDate').getValue())) {
        await $c.win.alert("End Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_startDate').getValue(), $c.util.getComponent('cal_endDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnFileDownReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnFileDownReq").set("method", "corpResearchReportList");
    $c.util.getComponent("dma_fnFileDownReq").set("forward", "corpResearchReport_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack1
 * @description fn Search Call Back1 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack1 = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnFileDownReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnFileDownReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnDetailView
 * @description fn Detail View 처리
 * @param {String} ipt_contnId ipt_contnId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDetailView = async function (ipt_contnId) {
    $c.util.getComponent("detailContents").setStyle("display", "");
    $c.util.getComponent("dma_fnFileDownReq").set("contnId", ipt_contnId);
    $c.util.getComponent("dma_fnFileDownReq").set("method", "corpResearchReportDetail");
    $c.util.getComponent("dma_fnFileDownReq").set("forward", "corpResearchReport_detail");
    await scwin.tx_fnDetailView_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack2
 * @description fn Search Call Back2 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack2 = function (data) {
    $("#detailContents").empty().append(data);
};

/**
 * @method
 * @name fnDetailClose
 * @description fn Detail Close 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnDetailClose = function () {
    $("#detailContents").empty();
    $c.util.getComponent("detailContents").setStyle("display", "none");
};

/**
 * @method
 * @name fnFileDown
 * @description fn File Down 처리
 * @param {String} ipt_resoroomId ipt_resoroomId
 * @param {*} ipt_attachSeq ipt_attachSeq
 * @param {String} ipt_attachFileNm ipt_attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnFileDown = async function (ipt_resoroomId, ipt_attachSeq, ipt_attachFileNm) {
    $c.util.getComponent("dma_fnFileDownReq").set("method", "downloadCorpReport");
    $c.util.getComponent("dma_fnFileDownReq").set("resoroomId", ipt_resoroomId);
    $c.util.getComponent("dma_fnFileDownReq").set("attachSeq", ipt_attachSeq);
    $c.util.getComponent("dma_fnFileDownReq").set("attachFileNm", ipt_attachFileNm);
    await scwin.tx_fnFileDown();
};
